// WiFi из файла на SD
bool connectWiFiFromSD() {
  File file = SD_MMC.open("/wifi.txt");
  if (!file) {
    Serial.println("Ошибка: /wifi.txt не найден");
    return false;
  }
  String content;
  while (file.available()) content += (char)file.read();
  file.close();
  content.trim();

  int comma = content.indexOf(',');
  if (comma == -1) {
    Serial.println("Ошибка: /wifi.txt должен содержать SSID,PASSWORD");
    return false;
  }
  String ssid = content.substring(0, comma);
  String pass = content.substring(comma + 1);
  ssid.trim(); pass.trim();

  Serial.printf("Подключение к Wi-Fi: %s\n", ssid.c_str());
  WiFi.begin(ssid.c_str(), pass.c_str());

  for (int i = 0; i < 20 && WiFi.status() != WL_CONNECTED; i++) {
    delay(500); Serial.print('.');
  }
  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("IP: "); Serial.println(WiFi.localIP());
    return true;
  }
  Serial.println("Wi-Fi: не удалось подключиться");
  return false;
}

void logData(float t, float h) {
  File file = SD_MMC.open("/data.csv", FILE_APPEND);
  if (!file) return;
  file.printf("%.1f,%.1f\n", t, h);
  file.close();
}

// /data.json — Потоковый экономичный стриминг данных из data.csv
void handleDataJson() {
  File file = SD_MMC.open("/data.csv");
  if (!file) {
    server.send(404, "application/json", "{\"error\":\"no data\"}");
    return;
  }

  server.setContentLength(CONTENT_LENGTH_UNKNOWN);
  server.send(200, "application/json", "");

  server.sendContent("[");
  bool first = true;

  while (file.available()) {
    String ln = file.readStringUntil('\n');
    ln.trim();
    int comma = ln.indexOf(',');
    if (comma == -1) continue;

    if (!first) server.sendContent(",");
    server.sendContent("{\"t\":" + ln.substring(0, comma) + ",\"h\":" + ln.substring(comma + 1) + "}");
    first = false;
  }
  file.close();
  server.sendContent("]");
}

