void setup() {
Serial.begin(115200);
dht.begin();
SD_MMC.setPins(SD_MMC_CLK, SD_MMC_CMD, SD_MMC_D0);
if (!SD_MMC.begin("/sdcard", true, true, SDMMC_FREQ_DEFAULT, 5)) {
Serial.println("Критическая ошибка: не удалось смонтировать SD карту");
return;
}
if (connectWiFiFromSD()) {
server.on("/", handleRoot);
server.on("/data.json", handleDataJson);
server.begin();
Serial.println("Метеостанция запущена!");
}
}
void loop() {
server.handleClient();
unsigned long currentMillis = millis();
// Опрос DHT11 каждые 5 секунд
if (currentMillis - lastDhtRead >= DHT_READ_INTERVAL_MS || lastDhtRead == 0) {
lastDhtRead = currentMillis;
float h = dht.readHumidity();
float t = dht.readTemperature();
if (!isnan(h) && !isnan(t)) {
curT = t;
curH = h;
hasData = true;
// Обновление экстремумов сессии
if (minT > 90.0 || curT < minT) minT = curT;
if (maxT < -90.0 || curT > maxT) maxT = curT;
if (minH > 99.0 || curH < minH) minH = curH;
if (maxH < 0.1 || curH > maxH) maxH = curH;
}
}
// Запись логов на SD карту ровно каждую 1 минуту
if (currentMillis - lastLogTime >= LOG_INTERVAL_MS || lastLogTime == 0) {
if (hasData && curT != 0.0) {
lastLogTime = currentMillis;
logData(curT, curH);
}
}
